style.css:
body {
  background: #0a192f;
  color: #e6f1ff;
}

button {
  background: #112240;
  color: white;
  border-radius: 8px;
}

input, textarea {
  background: #112240;
  color: white;
  border: 1px solid #233554;
}:root {
    --background-primary: #0a192f;
    --background-secondary: #112240;
    --background-tertiary: #233554;

    --text-primary: #e6f1ff;
    --text-secondary: #a8b2d1;

    --accent-primary: #64ffda;
    --accent-secondary: #4a90e2;
}

body {
    background-color: var(--background-primary);
    color: var(--text-primary);
}

button {
    background-color: var(--background-secondary);
    color: var(--text-primary);
    border-radius: 8px;
}
